using System;using System.IO;using System.Linq;using System.Xml.Linq;
static class GameIO{public static string Directory;public static string GetSaveGameDir()=>Directory;}
static class Log{public static void Warning(string x){}}
static class RebirthSurvivorRequestScope{public static bool TryNormalize(string s,out string normalized){normalized=s;return Guid.TryParseExact(s,"N",out var g);}}
static class RebirthAtomicXmlFile{
 public static int Fault;
 public static bool TryWrite(string path,XDocument doc,out string error){error="fault";Directory.CreateDirectory(Path.GetDirectoryName(path));if(Fault==1)return false;if(Fault==3)throw new IOException("uncertain");doc.Save(path);return Fault!=2;}
 public static bool TryLoadFinalThenBackup(string path,out XDocument doc,out bool backup,out string error){doc=null;backup=false;error="";try{doc=XDocument.Load(path);return true;}catch{try{doc=XDocument.Load(path+".bak");backup=true;return true;}catch{return false;}}}
}
class Test{
 static int count;static string FilePath=>Path.Combine(GameIO.Directory,"RebirthData","Survivor","TeachingOutcomes.xml");static void Check(bool x,string why){if(!x)throw new Exception(count+" "+why);count++;}
 static RebirthTeachingDurableOutcome New(string id)=>new RebirthTeachingDurableOutcome{OutcomeId=id,InstructorStorageKey="teacher",StudentStorageKey="student",InstructorCreationId=new string('a',32),StudentCreationId=new string('b',32),SkillId="skill.cooking",StudentKnowledgeTarget=42,HistoryKey="history",HistoryTargetCount=1,CompletedUtcTicks=10,TeacherAward=.4f};
 static void Main(string[] args){GameIO.Directory=args[0];string error;RebirthTeachingDurableOutcome original;var first=New("first");RebirthAtomicXmlFile.Fault=1;Check(!RebirthTeachingOutcomeStore.TryReserveOriginal(first,0,out error)&&first.OriginalOrdinal==1,"unknown preparation holds original ordinal");Check(RebirthTeachingOutcomeStore.Snapshot().Length==0,"unproved preparation hidden");RebirthAtomicXmlFile.Fault=0;Check(RebirthTeachingOutcomeStore.TryReserveOriginal(first,0,out error)&&first.OriginalOrdinal==1,"same request retries original");Check(RebirthTeachingOutcomeStore.TryGetOriginal(first,out original),"exact final original");Check(RebirthTeachingOutcomeStore.AcknowledgeStudent(first.OutcomeId),"student");Check(RebirthTeachingOutcomeStore.AcknowledgeInstructor(first.OutcomeId),"instructor");Check(RebirthTeachingOutcomeStore.AcknowledgeReward(first.OutcomeId)&&RebirthTeachingOutcomeStore.Snapshot().Length==1,"reward does not skip Solo");RebirthAtomicXmlFile.Fault=1;Check(!RebirthTeachingOutcomeStore.AcknowledgeSolo(first.OutcomeId),"terminal uncertainty held");Check(!RebirthTeachingOutcomeStore.AcknowledgeSolo(first.OutcomeId),"unknown missing terminal cannot be claimed");RebirthAtomicXmlFile.Fault=0;Check(RebirthTeachingOutcomeStore.AcknowledgeSolo(first.OutcomeId)&&RebirthTeachingOutcomeStore.Snapshot().Length==0,"same terminal reconciliation");Check(!RebirthTeachingOutcomeStore.TryReserveOriginal(first,0,out error),"retired original denied");RebirthTeachingOutcomeStore.Reset();var second=New("second");Check(RebirthTeachingOutcomeStore.TryReserveOriginal(second,1,out error)&&second.OriginalOrdinal==2,"reload maintains issued ordinal");Check(!RebirthTeachingOutcomeStore.TryReserveOriginal(New("second"),0,out error)==false,"same immutable request stable");var foreign=second.Clone();foreign.StudentKnowledgeTarget=43;Check(!RebirthTeachingOutcomeStore.TryGetOriginal(foreign,out original),"altered outcome denied");RebirthAtomicXmlFile.Fault=2;var third=New("third");Check(RebirthTeachingOutcomeStore.TryReserveOriginal(third,100,out error)&&third.OriginalOrdinal==101,"false return with exact final proves original");RebirthAtomicXmlFile.Fault=3;var fourth=New("fourth");try{RebirthTeachingOutcomeStore.TryReserveOriginal(fourth,0,out error);throw new Exception("missing throw");}catch(IOException){}Check(fourth.OriginalOrdinal==102,"throw retains allocation");RebirthAtomicXmlFile.Fault=0;Check(RebirthTeachingOutcomeStore.TryReserveOriginal(fourth,0,out error)&&fourth.OriginalOrdinal==102,"throw retry same ordinal");var doc=XDocument.Load(FilePath);doc.Root.SetAttributeValue("extra",1);doc.Save(FilePath);RebirthTeachingOutcomeStore.Reset();Check(RebirthTeachingOutcomeStore.Snapshot().Length==0,"strict root rejects unknown schema");doc.Root.Attribute("extra").Remove();doc.Root.SetAttributeValue("version",2);doc.Root.Attribute("issued").Remove();foreach(var row in doc.Root.Elements()){row.Attribute("originalOrdinal").Remove();row.Attribute("soloApplied").Remove();}doc.Save(FilePath);RebirthTeachingOutcomeStore.Reset();var legacy=RebirthTeachingOutcomeStore.Snapshot();Check(legacy.Length==3&&legacy.All(x=>x.OriginalOrdinal==0&&x.SoloEvidenceApplied),"legacy migration has no retroactive original evidence");var fifth=New("fifth");Check(RebirthTeachingOutcomeStore.TryReserveOriginal(fifth,102,out error)&&fifth.OriginalOrdinal==103,"saved character floor survives legacy journal restore");Check(!RebirthTeachingOutcomeStore.TryReserveOriginal(New("bad"),long.MaxValue,out error),"overflow refuses allocation");Console.WriteLine(count+" PASS actual original Teaching outcome journal");}
}